-- Valor Housing complaints register, 1 August to 4 November 2026 (38 complaints, all resolved), added on 3 Nov 2026 at
-- the owner's request from Valor_Housing_..._Complaints_Register_Aug-Nov_2026.xlsx. The owner confirmed that the
-- workbook's "hypothetical" template labels were left in by mistake and the records are actual. Each case keeps the
-- register's received, acknowledged and resolved dates; a timeline note records when and from where it was added.
-- Complainants are anonymised residents (no names or tenant refs). Linked to the Hub property where the address
-- matches (15 of 19 addresses); the other four keep the address in the summary. The register's managing-agent column
-- is not used: the owner confirmed Valor Housing is the managing agent, so the 15 properties are set to that.
-- Logged by the first super administrator. Skipped without Valor Housing or a super administrator; never added twice.
do $$
declare co uuid; who uuid; r record; cid uuid; pid uuid;
begin
  select id into co from companies where code = 'VH';
  select person_id into who from role_grants where role_key = 'super_admin' order by valid_from limit 1;
  if co is null or who is null then return; end if;
  update properties set managing_agent = 'Valor Housing'
   where company_id = co and ref in ('VH-HOL106','VH-CLA011','VH-GRO119','VH-HAG179A','VH-OXH203','VH-WES227','VH-RIC026','VH-CHU032','VH-CRO033','VH-LUD037','VH-SHA005','VH-FAR052','VH-MUR062','VH-JAC1','VH-JAC2');
