    ('VH-26-038', 'VH-HYP-26-038', date '2026-10-28', null, '8 Foxwell Grove, Birmingham', 'email', 'repairs', 'repairs', 'low', 'Kitchen drawer runner sticking', 'Resident reported a shared kitchen drawer would not close smoothly.', date '2026-10-29', 'Maintenance Coordinator', 'Drawer runner adjusted and operation checked.', date '2026-10-30', date '2026-11-11')
  ) t(rid, orig, received, pref, address, channel, category, dept, priority, title, descr, acked, owner_role, action, resolved, due)
  loop
    continue when exists (select 1 from property_complaints where company_id = co and title = r.title || ' (' || r.rid || ')');
    pid := (select id from properties where company_id = co and ref = r.pref);
    insert into property_complaints (company_id, property_id, raised_by, source, channel, category, summary, title, department, priority, due_on, stage,
                                     resolution, resolved_at, created_at, updated_at)
    values (co, pid, who, 'resident', r.channel, r.category,
            r.descr || case when pid is null then ' Property: ' || r.address || '.' else '' end,
            r.title || ' (' || r.rid || ')', r.dept, r.priority, r.due, 'resolved',
            r.action || ' Action owner: ' || r.owner_role || '. Complainant informed of the outcome.',
            r.resolved::timestamptz + interval '12 hours', r.received::timestamptz + interval '9 hours', r.resolved::timestamptz + interval '12 hours')
    returning id into cid;
    insert into complaint_events (complaint_id, actor_id, kind, body, meta, created_at)
      values (cid, who, 'stage', r.action, jsonb_build_object('from', 'new', 'to', 'resolved'), r.resolved::timestamptz + interval '12 hours');
    insert into complaint_events (complaint_id, actor_id, kind, body, created_at) values
      (cid, who, 'created', 'Complaint received (' || replace(r.channel, '_', ' ') || ').', r.received::timestamptz + interval '9 hours'),
      (cid, who, 'note', 'Acknowledged.', r.acked::timestamptz + interval '10 hours'),
      (cid, who, 'note', 'Added to the Hub on 3 Nov 2026 from Valor''s complaints register (register ID ' || r.orig || ').', now());
  end loop;
end $$;
